metadata.fact_probe:
#include <tests.h>
string nm;
void setn(string s) { nm = s; }
string who() { return nm; }
void sh(object t) { shadow(t, 1); }
void do_tests() {
    object b = new(file_name()), s1 = new(file_name()), s2 = new(file_name());
    b->setn("base"); s1->setn("s1"); s2->setn("s2");
    s1->sh(b); s2->sh(b);
    ASSERT_EQ("s2", s1->who());
    ASSERT_EQ("s2", b->who());
}
